//! Per-camera colour matrices for raw files that embed none (#1465).
//!
//! Generated by scripts/gen-camera-matrices.py; do not edit. Most matrices are
//! fitted from camera spectral sensitivities in AcademySoftwareFoundation/
//! rawtoaces-data (Apache-2.0) under CIE illuminants A and D65, with the CIE
//! 1931 observer. Panasonic bodies without published sensitivities take
//! approximate matrices fitted from their own camera JPEGs (#1542,
//! scripts/fit-camera-jpeg-matrices.py). No Adobe or dcraw matrix is used. See
//! assets/PROVENANCE.md. `model` keys are normalized by `vendor::model_key`.

/// One camera's fitted XYZ → camera matrices, row-major, each with the EXIF
/// `LightSource` code of the light it was fitted under (one or two).
pub(super) struct CameraMatrices {
    pub make: &'static str,
    pub models: &'static [&'static str],
    pub matrices: &'static [(u16, [f64; 9])],
}

